import random
import itertools

def count_monochromatic_k5(n, edges):
    # edges is a dictionary: (i, j) -> color (0 or 1)
    # where i < j
    count = 0
    for clique in itertools.combinations(range(n), 5):
        # Check if all edges in the clique have the same color
        clique_edges = []
        for i, j in itertools.combinations(clique, 2):
            if i > j:
                i, j = j, i
            clique_edges.append(edges[(i, j)])

        if all(c == 0 for c in clique_edges) or all(c == 1 for c in clique_edges):
            count += 1
    return count

def solve():
    n = 21
    edges = {}
    # Initialize with random colors
    for i in range(n):
        for j in range(i + 1, n):
            edges[(i, j)] = random.randint(0, 1)

    # Local search
    for iteration in range(10000):
        # Find all monochromatic K5s
        monochromatic_k5s = []
        for clique in itertools.combinations(range(n), 5):
            clique_edges = []
            for i, j in itertools.combinations(clique, 2):
                if i > j:
                    i, j = j, i
                clique_edges.append((i, j))

            colors = [edges[e] for e in clique_edges]
            if all(c == 0 for c in colors) or all(c == 1 for c in colors):
                monochromatic_k5s.append(clique_edges)

        if not monochromatic_k5s:
            return edges

        # Pick a random monochromatic K5 and flip one of its edges
        clique_edges = random.choice(monochromatic_k5s)
        edge_to_flip = random.choice(clique_edges)
        edges[edge_to_flip] = 1 - edges[edge_to_flip]

    return None

result = solve()
if result:
    # Format the result as a list of 210 integers
    output = []
    for i in range(21):
        for j in range(i + 1, 21):
            output.append(result[(i, j)])
    print(output)
else:
    print("Failed")
